    Witness w(3);  // 最多存储 3 个请求

    w.record("master1", "key1", 1, {});
    w.record("master1", "key2", 2, {});
    w.record("master1", "key3", 3, {});

    // 第 4 个请求应该被拒绝
    auto r = w.record("master1", "key4", 4, {});
    EXPECT_EQ(r, Witness::RecordResult::REJECTED_NO_SPACE);
}

// 测试：垃圾回收
